import{_ as e,o as a,c as o,a5 as r}from"./chunks/framework.BPFk9-tb.js";const f=JSON.parse('{"title":"写作课作业-064","description":"","frontmatter":{"date":"2020-09-22T08:35:57","title":"写作课作业-064","categories":["写作","作业"],"tags":["写作","作业"]},"headers":[],"relativePath":"posts/homework/064.md","filePath":"posts/homework/064.md"}'),p={name:"posts/homework/064.md"};function s(_,t,l,c,h,m){return a(),o("div",null,[...t[0]||(t[0]=[r('<blockquote><p>9.21写作作业：学习就是重复再重复，写作课笑来居然没有放回放，而是重复讲，亿万富翁还如此深久狠，请重复听一次写作课第一课，谈谈对“你们正在由衷地虚伪地认真记着笔记”的理解。</p></blockquote><blockquote><p><a href="./名词.html">你们</a> 正在 <a href="./副词.html">由衷地</a> <a href="./副词.html">虚伪地</a> <a href="./副词.html">认真地</a><a href="./动词.html">记着</a><a href="./名词.html">笔记</a>。</p></blockquote><p>为什么笑来老师能传递这样的感知？通过听课大致可以知道，教过大量的学生，不断的琢磨、反复的练习。就连《肖申克的救赎》的作者斯蒂芬·金都建议不要使用的副词，也能使用得如此熟练，那得经过多少次的练习呢？</p><p>笑来老师第二期开课，没有放回放，没有错过自己又一次打磨课程的机会。而自己清晰的记得，曾经给一个客户写升级报告，被要求改了几次，心里就非常的不爽。要重复不是一件容易的事情，如果是被要求的那就更难了。</p><p>自己能否就用三个不同的副词来形容正在做作业的自己呢？答案是办不到，为什么呢？其中一个原因是不愿意不断的想，当思维开始接受挑战的时候就想着放弃。罗子雄的TEDxChongqing的分享《如何成为一名优秀的设计师》，其中一段描述如何入门，就说要不断的想，不停的问自己为什么？</p><p>自己写代码的时候，经常会花一些时间重构自己的代码。现在自己写作业的时候，也要花很多时间，看似绞尽脑汁，结果连个屁也没放出来。现在的输入，处理，输出的各个环节对自己来说都挺难的。但用笑来老师的话来说，这才哪到哪啊——如果按1万小时定律来算，每天两小时——我起码需要13年的时间来打磨我的写作能力。</p><p>完成比完美更重要，所以就算我虚伪，我痛苦，也要由衷地认真地完成作业，先让写作成为自己的一个习惯。</p>',7)])])}const i=e(p,[["render",s]]);export{f as __pageData,i as default};
